### 1. Python (FastAPI + Pydantic)
Contoh endpoint asynchronous dengan validasi tipe data bawaan:

```python
from fastapi import FastAPI, HTTPException, Depends
from pydantic import BaseModel, EmailStr
from typing import List, Optional
import asyncpg

app = FastAPI(title="Devnuby AI Core Service")

class UserPayload(BaseModel):
    username: str
    email: EmailStr
    role: Optional[str] = "developer"

@app.post("/api/v1/users", status_code=201)
async def create_user(payload: UserPayload):
    # Query database secara async dengan parameter terisolasi
    query = """
        INSERT INTO users (username, email, role)
        VALUES ($1, $2, $3)
        RETURNING id, created_at;
    """
    try:
        row = await db.fetchrow(query, payload.username, payload.email, payload.role)
        return {"status": "ok", "user_id": row["id"], "data": payload.dict()}
    except Exception as exc:
        raise HTTPException(status_code=500, detail=str(exc))
```

