### 2. JavaScript / TypeScript (Node.js + Express)
Contoh controller Express modern menggunakan TypeScript & async/await:

```typescript
import { Request, Response, NextFunction } from "express";
import { db } from "./database";

interface CreateProjectBody {
  name: string;
  repositoryUrl: string;
  isPrivate?: boolean;
}

export async function handleCreateProject(
  req: Request<{}, {}, CreateProjectBody>,
  res: Response,
  next: NextFunction
): Promise<void> {
  const { name, repositoryUrl, isPrivate = true } = req.body;

  if (!name || !repositoryUrl) {
    res.status(400).json({ error: "Name and repository URL are required" });
    return;
  }

  try {
    const [project] = await db("projects")
      .insert({
        name,
        repository_url: repositoryUrl,
        is_private: isPrivate,
        created_at: new Date(),
      })
      .returning(["id", "name", "created_at"]);

    res.status(201).json({ success: true, data: project });
  } catch (err) {
    next(err);
  }
}
```

