### 4. Go (Golang Standard Library `net/http`)
Contoh server Go berkinerja tinggi tanpa dependensi eksternal yang berlebihan:

```go
package main

import (
	"encoding/json"
	"log"
	"net/http"
	"time"
)

type SessionResponse struct {
	ID        string    `json:"id"`
	Model     string    `json:"model"`
	Active    bool      `json:"active"`
	CreatedAt time.Time `json:"created_at"`
}

func sessionHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	if r.Method != http.MethodGet {
		http.Error(w, `{"error": "Method not allowed"}`, http.StatusMethodNotAllowed)
		return
	}

	resp := SessionResponse{
		ID:        "sess-preview-demo",
		Model:     "claude-sonnet-4-5",
		Active:    true,
		CreatedAt: time.Now().UTC(),
	}

	if err := json.NewEncoder(w).Encode(resp); err != nil {
		log.Printf("Failed to encode response: %v", err)
	}
}

func main() {
	http.HandleFunc("/api/v1/session", sessionHandler)
	log.Println("Devnuby Go backend running on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
```

